    { path: '/taichu/cs/dashboard', name: 'CsDashboard', component: () => import('@/views/太初俱乐部/CsDashboard.vue') },
    { path: '/taichu/my-complaints', name: 'MyComplaints', component: () => import('@/views/太初俱乐部/MyComplaints.vue') },
